import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

/**
 * Exports a Three.js scene to OBJ format with Blender Z-up coordinate system.
 * Applies -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up.
 */
class OBJExporter {
  constructor() {
    this.output = '';
    this.vertexOffset = 1; // OBJ indices start at 1
  }

  /**
   * Main export function
   */
  export(scene) {
    this.output = '# Exported from Three.js to Blender Z-up OBJ\n';
    this.output += '# -90 degree X-rotation applied for coordinate system conversion\n\n';

    // Create transformation matrix for Blender Z-up (-90° X-rotation)
    const blenderTransform = new THREE.Matrix4();
    blenderTransform.makeRotationX(-Math.PI / 2);

    // Process the scene
    this.processObject(scene, blenderTransform);

    return this.output;
  }

  /**
   * Recursively process objects in the scene
   */
  processObject(object, parentMatrix) {
    // Compute world matrix for this object
    const worldMatrix = new THREE.Matrix4();
    worldMatrix.copy(parentMatrix);

    // Apply local transformations
    const localMatrix = new THREE.Matrix4();
    localMatrix.compose(object.position, object.quaternion, object.scale);
    worldMatrix.multiply(localMatrix);

    // Handle different object types
    if (object instanceof THREE.Mesh) {
      this.exportMesh(object, worldMatrix);
    } else if (object instanceof THREE.InstancedMesh) {
      this.exportInstancedMesh(object, worldMatrix);
    }

    // Recursively process children
    if (object.children && object.children.length > 0) {
      for (const child of object.children) {
        this.processObject(child, worldMatrix);
      }
    }
  }

  /**
   * Export a regular mesh
   */
  exportMesh(mesh, worldMatrix) {
    const geometry = mesh.geometry;

    if (!geometry || !geometry.attributes.position) {
      return;
    }

    this.output += `\n# Object: ${mesh.name || 'unnamed'}\n`;
    this.output += `o ${mesh.name || 'mesh_' + this.vertexOffset}\n`;

    const positions = geometry.attributes.position.array;
    const indices = geometry.index ? geometry.index.array : null;

    // Export vertices
    const startVertexIndex = this.vertexOffset;
    const vertexCount = positions.length / 3;

    for (let i = 0; i < vertexCount; i++) {
      const vertex = new THREE.Vector3(
        positions[i * 3],
        positions[i * 3 + 1],
        positions[i * 3 + 2]
      );

      // Apply world transformation
      vertex.applyMatrix4(worldMatrix);

      this.output += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
    }

    // Export faces
    if (indices) {
      // Indexed geometry
      for (let i = 0; i < indices.length; i += 3) {
        const v1 = startVertexIndex + indices[i];
        const v2 = startVertexIndex + indices[i + 1];
        const v3 = startVertexIndex + indices[i + 2];
        this.output += `f ${v1} ${v2} ${v3}\n`;
      }
    } else {
      // Non-indexed geometry
      for (let i = 0; i < vertexCount; i += 3) {
        const v1 = startVertexIndex + i;
        const v2 = startVertexIndex + i + 1;
        const v3 = startVertexIndex + i + 2;
        this.output += `f ${v1} ${v2} ${v3}\n`;
      }
    }

    this.vertexOffset += vertexCount;
  }

  /**
   * Export an instanced mesh
   */
  exportInstancedMesh(instancedMesh, worldMatrix) {
    const geometry = instancedMesh.geometry;
    const count = instancedMesh.count;

    if (!geometry || !geometry.attributes.position) {
      return;
    }

    const positions = geometry.attributes.position.array;
    const indices = geometry.index ? geometry.index.array : null;
    const vertexCount = positions.length / 3;

    // Export each instance as a separate object
    for (let instanceIndex = 0; instanceIndex < count; instanceIndex++) {
      this.output += `\n# Instanced Object: ${instancedMesh.name || 'unnamed'} [${instanceIndex}]\n`;
      this.output += `o ${instancedMesh.name || 'instance'}_${instanceIndex}\n`;

      // Get instance matrix
      const instanceMatrix = new THREE.Matrix4();
      instancedMesh.getMatrixAt(instanceIndex, instanceMatrix);

      // Combine world matrix with instance matrix
      const finalMatrix = new THREE.Matrix4();
      finalMatrix.copy(worldMatrix);
      finalMatrix.multiply(instanceMatrix);

      // Export vertices for this instance
      const startVertexIndex = this.vertexOffset;

      for (let i = 0; i < vertexCount; i++) {
        const vertex = new THREE.Vector3(
          positions[i * 3],
          positions[i * 3 + 1],
          positions[i * 3 + 2]
        );

        // Apply final transformation
        vertex.applyMatrix4(finalMatrix);

        this.output += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
      }

      // Export faces for this instance
      if (indices) {
        for (let i = 0; i < indices.length; i += 3) {
          const v1 = startVertexIndex + indices[i];
          const v2 = startVertexIndex + indices[i + 1];
          const v3 = startVertexIndex + indices[i + 2];
          this.output += `f ${v1} ${v2} ${v3}\n`;
        }
      } else {
        for (let i = 0; i < vertexCount; i += 3) {
          const v1 = startVertexIndex + i;
          const v2 = startVertexIndex + i + 1;
          const v3 = startVertexIndex + i + 2;
          this.output += `f ${v1} ${v2} ${v3}\n`;
        }
      }

      this.vertexOffset += vertexCount;
    }
  }
}

/**
 * Main execution
 */
function main() {
  console.log('Creating Three.js scene...');
  const scene = createScene();

  console.log('Exporting to OBJ format with Blender Z-up transformation...');
  const exporter = new OBJExporter();
  const objContent = exporter.export(scene);

  // Ensure output directory exists
  const outputDir = '/root/output';
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Write OBJ file
  const outputPath = path.join(outputDir, 'object.obj');
  fs.writeFileSync(outputPath, objContent, 'utf8');

  console.log(`Successfully exported to: ${outputPath}`);
  console.log(`Total vertices: ${exporter.vertexOffset - 1}`);
}

main();

